with filtered as (select id, customer_id, order_date, status, channel, amount, shipping_fee, lower(channel) as channel_lower, floor(shipping_fee) as shipping_fee_whole, coalesce(channel, 'N/A') as resolved_channel from orders where order_date >= date '2023-06-27' and channel is distinct from 'web') select s.* from filtered s where exists (select 1 from shipments ch where ch.order_id = s.id and ch.shipped_date <= s.order_date);
